function admitAsana(raw, headers, secret, crypto) {
  const reply = (status, error) => ({
    accepted: false,
    handshake: false,
    status,
    response: { error },
  });
  const setup = headers?.["x-hook-secret"];
  if (!secret) {
    if (
      typeof setup === "string" &&
      /^[a-f0-9]{32,128}$/i.test(setup) &&
      !headers?.["x-hook-signature"]
    ) {
      return { accepted: false, handshake: true, challenge: setup };
    }
    return reply(503, "Configure the Asana webhook signing secret.");
  }
  const supplied = headers?.["x-hook-signature"];
  if (
    typeof supplied !== "string" ||
    !/^[a-f0-9]{64}$/i.test(supplied) ||
    !raw?.length ||
    raw.length > 1048576
  ) {
    return reply(401, "Invalid Asana webhook signature.");
  }
  const expected = crypto.createHmac("sha256", secret).update(raw).digest();
  if (!crypto.timingSafeEqual(expected, Buffer.from(supplied, "hex")))
    return reply(401, "Invalid Asana webhook signature.");
  let body;
  try {
    body = JSON.parse(raw.toString("utf8"));
  } catch {
    return reply(400, "Invalid Asana event payload.");
  }
  if (!Array.isArray(body?.events)) return reply(400, "Invalid Asana event payload.");
  const gids = new Set();
  for (const { resource, action } of body.events.filter(
    (event) => event && typeof event === "object",
  )) {
    if (resource?.resource_type !== "task" || ["deleted", "removed"].includes(action)) continue;
    if (typeof resource.gid !== "string" || !/^\d{1,32}$/.test(resource.gid))
      return reply(400, "Invalid Asana task ID.");
    gids.add(resource.gid);
  }
  return { accepted: true, gids: [...gids] };
}
const crypto = require("crypto");
let raw, secret;
try {
  raw = Buffer.from(await helpers.getBinaryDataBuffer(0, "data"));
} catch {}
try {
  secret = $env.ASANA_WEBHOOK_SECRET;
} catch {
  return {
    json: {
      accepted: false,
      handshake: false,
      status: 503,
      response: { error: "Signing secret configuration is unavailable." },
    },
  };
}
return { json: admitAsana(raw, $json.headers, secret, crypto) };

const settings = {
  projectId: "YOUR_ASANA_PROJECT_GID",
  dataSourceId: "YOUR_NOTION_DATA_SOURCE_ID",
};
if (
  !/^\d{1,32}$/.test(settings.projectId) ||
  !/^[0-9a-f]{8}(?:-[0-9a-f]{4}){3}-[0-9a-f]{12}$/i.test(settings.dataSourceId)
) {
  throw new Error("Configure the Asana project and Notion data source.");
}
return $input.first().json.gids.map((gid) => ({ json: { gid, ...settings } }));

function checkedAsanaTask(status, response, gid, projectId) {
  if (status === 404) return { next: false };
  const task = response?.data;
  if (
    status !== 200 ||
    task?.gid !== gid ||
    typeof task.name !== "string" ||
    !task.name.trim() ||
    task.name.length > 2000 ||
    !Array.isArray(task.memberships) ||
    !(
      task.due_on === null ||
      (typeof task.due_on === "string" && /^\d{4}-\d{2}-\d{2}$/.test(task.due_on))
    )
  ) {
    throw new Error("Asana did not return scheduling data for task " + gid + ".");
  }
  if (!task.memberships.some((membership) => membership?.project?.gid === projectId))
    return { next: false };
  return { next: true, gid, name: task.name, due: task.due_on };
}

const input = $("Handle one task at a time").item.json;
return {
  json: {
    ...checkedAsanaTask($json.statusCode, $json.body, input.gid, input.projectId),
    dataSourceId: input.dataSourceId,
  },
};

function notionText(items) {
  if (!Array.isArray(items)) return null;
  const text = items.map((part) => part?.plain_text ?? part?.text?.content);
  return text.every((part) => typeof part === "string") ? text.join("") : null;
}

function planNotionTask(status, query, task, dataSourceId) {
  if (
    status !== 200 ||
    !Array.isArray(query?.results) ||
    query.has_more !== false ||
    query.results.length > 1
  ) {
    throw new Error("Notion did not return a unique lookup for Asana task " + task.gid + ".");
  }
  const equalId = (a, b) =>
    typeof a === "string" &&
    a.replaceAll("-", "").toLowerCase() === b.replaceAll("-", "").toLowerCase();
  const existing = query.results[0];
  if (existing !== undefined) {
    const prop = existing?.properties?.["Asana GID"];
    if (
      existing?.object !== "page" ||
      typeof existing.id !== "string" ||
      !/^[0-9a-f]{8}(?:-[0-9a-f]{4}){3}-[0-9a-f]{12}$/i.test(existing.id) ||
      existing.parent?.type !== "data_source_id" ||
      !equalId(existing.parent.data_source_id, dataSourceId) ||
      prop?.type !== "rich_text" ||
      notionText(prop.rich_text) !== task.gid
    ) {
      throw new Error("The Notion page does not match Asana task " + task.gid + ".");
    }
  }
  const block = (content) => [{ type: "text", text: { content } }];
  const properties = {
    Task: { title: block(task.name) },
    Deadline: { date: task.due === null ? null : { start: task.due } },
  };
  const expect = { ...task, dataSourceId, pageId: existing?.id ?? null };
  if (existing)
    return { method: "PATCH", endpoint: "/pages/" + existing.id, body: { properties }, expect };
  properties["Asana GID"] = { rich_text: block(task.gid) };
  return {
    method: "POST",
    endpoint: "/pages",
    body: { parent: { type: "data_source_id", data_source_id: dataSourceId }, properties },
    expect,
  };
}

const task = $("Confirm the task and project").item.json;
return { json: planNotionTask($json.statusCode, $json.body, task, task.dataSourceId) };

function notionText(items) {
  if (!Array.isArray(items)) return null;
  const text = items.map((part) => part?.plain_text ?? part?.text?.content);
  return text.every((part) => typeof part === "string") ? text.join("") : null;
}

function confirmNotionTask(status, page, expected) {
  const equalId = (a, b) =>
    typeof a === "string" &&
    a.replaceAll("-", "").toLowerCase() === b.replaceAll("-", "").toLowerCase();
  const props = page?.properties;
  const due = props?.Deadline?.date;
  if (
    (status !== 200 && status !== 201) ||
    page?.object !== "page" ||
    typeof page.id !== "string" ||
    !page.id ||
    (expected.pageId !== null && !equalId(page.id, expected.pageId)) ||
    page.parent?.type !== "data_source_id" ||
    !equalId(page.parent.data_source_id, expected.dataSourceId) ||
    notionText(props?.["Asana GID"]?.rich_text) !== expected.gid ||
    notionText(props?.Task?.title) !== expected.name ||
    (expected.due === null ? due !== null : due?.start !== expected.due)
  ) {
    throw new Error(
      "Notion did not confirm Asana task " +
        expected.gid +
        ". Check the data source before retrying.",
    );
  }
  return {
    asanaGid: expected.gid,
    notionPageId: page.id,
    action: expected.pageId === null ? "created" : "updated",
  };
}

return {
  json: confirmNotionTask(
    $json.statusCode,
    $json.body,
    $("Choose create or update").item.json.expect,
  ),
};
